531	+
532	+export const EMPTY_TALLY: Tally = [0, 0];
533	+
534	+/** The tally after a match `winner` won - a draw (null) counts for nobody. */
535	+export function countResult(tally: Tally, winner: 0 | 1 | null): Tally {
536	+  if (winner === null) {
537	+    return tally;
