542	+/**
543	+ * Counts the wins of the matches two devices played over one connection,
544	+ * for the room both players see. A new connection starts at nought; the
545	+ * end of one keeps its count, so its last result still shows it.
546	+ */
547	+@Injectable({ providedIn: 'root' })
548	+export class RoomTally {
